def get_pattern(animal, state="standing", size="detail", facing_left=False):
    rows = (DETAIL_PATTERNS[animal][state] if size == "detail" else
            SCENE_PATTERNS[animal] if size == "scene" else ICON_PATTERNS[animal])
    return tuple(row[::-1] for row in rows) if facing_left else tuple(rows)

# Shorten only the projecting muzzle; preserve head, ears and connected body.
_MUZZLE_CUTS = {
    'dog': {'standing': {7: 34, 8: 34, 9: 34, 10: 33},
            'sitting': {6: 33, 7: 33, 8: 33},
            'petting': {7: 34, 8: 34, 9: 34, 10: 33}},
    'cat': {'standing': {9: 34, 10: 33, 11: 33},
            'sitting': {7: 31, 8: 30, 9: 30},
            'petting': {9: 34, 10: 33, 11: 33}},
}
for _species, _poses in _MUZZLE_CUTS.items():
    for _pose, _cuts in _poses.items():
        _rows=list(DETAIL_PATTERNS[_species][_pose])
        for _row, _start in _cuts.items():
            _rows[_row]=_rows[_row][:_start]+'0'*(len(_rows[_row])-_start)
        DETAIL_PATTERNS[_species][_pose]=tuple(_rows)
ICON_PATTERNS['dog'][1]='0011110'
for _species, _rows in [('dog',(1,2)),('cat',(3,))]:
    for _row in _rows:
        SCENE_PATTERNS[_species][_row]=SCENE_PATTERNS[_species][_row][:18]+'00'

# Recognition update (root README, "Tactile design rules"): the cat and dog drawings above shared one
# body and differed only in small head details. They are replaced by shapes built in shapes.py, where
# each species keeps its own distinguishing features in every pose (cat: tall pointed ears, upright
# curling tail, slim legs; dog: long snout, floppy ear, thick legs, short raised tail).
from .shapes import DETAIL as _DETAIL
for _species, _poses in _DETAIL.items():
    DETAIL_PATTERNS[_species] = dict(_poses)
# 7x5 icons: cat = two ear points and a raised tail; dog = long snout and a floppy ear.
